# Exercise: the data model traps (mutable defaults, late-binding closures, aliasing, copying).
# Run its test: python interviews/coframe_builds/python-data-model_test.py
import copy
import functools

_MISSING = object()  # sentinel for "not passed" when None is a valid value


def bad_append(x, acc=[]):  # default evaluated once, at def time: shared by every call
    acc.append(x)
    return acc


def good_append(x, acc=None):
    acc = [] if acc is None else acc
    acc.append(x)
    return acc


def late_bound():
    return [lambda: i for i in range(3)]  # each lambda reads i when called


def bound_now():
    return [lambda i=i: i for i in range(3)]  # default binds the value per iteration


def bound_partial():
    return [functools.partial(lambda i: i, i) for i in range(3)]


def aliased_rows(n):
    return [[0]] * n  # n references to ONE inner list


def fresh_rows(n):
    return [[0] for _ in range(n)]


def tuple_iadd():
    t = ([1], 2)
    try:
        t[0] += [3]  # list.__iadd__ mutates in place, then t[0] = ... fails
    except TypeError:
        return t, True
    return t, False


def copies(a):
    return copy.copy(a), copy.deepcopy(a)

# Exercise: a lazy generator pipeline (read, filter, parse, batch), yield from, and close().
# Run its test: python interviews/coframe_builds/python-iteration_test.py
import itertools
import json


def read_lines(src):
    for line in src:
        yield line.rstrip("\n")


def nonblank(lines):
    return (l for l in lines if l)


def parse(lines):
    for l in lines:
        yield json.loads(l)


def pipeline(src, n):
    # nothing is materialised until the caller pulls a batch
    return itertools.batched(parse(nonblank(read_lines(src))), n)


def inner():
    got = yield 1
    return f"inner got {got}"


def outer():
    r = yield from inner()  # send() passes through; r is inner's return value
    yield r


def cleanup_gen(log):
    try:
        yield 1
        yield 2
    finally:
        log.append("closed")  # runs on close(): GeneratorExit is raised at the yield


def count_sessions(lines):
    # constant memory per session, not per line: a dict of small aggregates
    counts = {}
    for l in lines:
        sid = l.split(",", 1)[0]
        counts[sid] = counts.get(sid, 0) + 1
    return counts

# Exercise: what the GIL does not protect (a shared counter), and keeping a blocking call off the event loop.
# Run its test: python interviews/coframe_builds/python-gil_test.py
import asyncio
import threading
import time


class Counter:
    def __init__(self):
        self.n = 0
        self._lock = threading.Lock()

    def incr_unsafe(self):
        self.n += 1  # read, add, store: a thread switch can land between them

    def incr(self):
        with self._lock:
            self.n += 1


def hammer(counter, threads=4, each=10_000):
    ts = [threading.Thread(target=lambda: [counter.incr() for _ in range(each)]) for _ in range(threads)]
    for t in ts:
        t.start()
    for t in ts:
        t.join()
    return counter.n


def blocking_sdk_call(s):
    time.sleep(s)  # stands in for a sync SDK with no async API
    return s


async def fan_out_blocking(n, s):
    # to_thread runs each call in the default thread pool; the GIL is released while it sleeps
    return await asyncio.gather(*(asyncio.to_thread(blocking_sdk_call, s) for _ in range(n)))

