# Exercise: descriptors, __slots__, a sync-or-async tracing decorator, and contextvars for a run id.
# Run its test: python interviews/coframe_builds/python-runtime-hooks_test.py
import contextvars
import functools
import inspect
import time
from collections.abc import Callable
from dataclasses import dataclass, field

run_id: contextvars.ContextVar[str] = contextvars.ContextVar("run_id", default="-")  # module level, always


class Positive:  # a data descriptor: defines __set__, so it beats the instance __dict__
    def __set_name__(self, owner, name):
        self.attr = "_" + name

    def __get__(self, obj, objtype=None):
        return self if obj is None else getattr(obj, self.attr)

    def __set__(self, obj, v):
        if v <= 0:
            raise ValueError("must be positive")
        setattr(obj, self.attr, v)


class Cfg:
    retries = Positive()

    def __init__(self, r):
        self.retries = r


@dataclass(slots=True, frozen=True)
class Span:
    name: str
    tags: list[str] = field(default_factory=list)


def naive_timed(fn, log):  # the bug: on an async def this times creating the coroutine, not running it
    @functools.wraps(fn)
    def wrap(*a, **k):
        t0 = time.perf_counter()
        try:
            return fn(*a, **k)
        finally:
            log.append(time.perf_counter() - t0)

    return wrap


def traced[**P, R](fn: Callable[P, R], log: list) -> Callable[P, R]:
    if inspect.iscoroutinefunction(fn):

        @functools.wraps(fn)
        async def awrap(*a: P.args, **k: P.kwargs):
            t0 = time.perf_counter()
            try:
                return await fn(*a, **k)
            finally:
                log.append((run_id.get(), time.perf_counter() - t0))

        return awrap  # type: ignore[return-value]

    @functools.wraps(fn)
    def wrap(*a: P.args, **k: P.kwargs) -> R:
        t0 = time.perf_counter()
        try:
            return fn(*a, **k)
        finally:
            log.append((run_id.get(), time.perf_counter() - t0))

    return wrap

# Exercise: test seams and memory diagnosis: an injectable model client, patch-where-used, tracemalloc diffs.
# Run its test: python interviews/coframe_builds/python-tooling_test.py
import tracemalloc
from os import getcwd  # this module now holds its own reference: patch python_tooling.getcwd, not os.getcwd


def where():
    return getcwd()


class Agent:
    def __init__(self, client):  # injected: tests pass a fake, never the network
        self.client = client
        self.history = []  # per-instance, never a module-level list

    def ask(self, q):
        self.history.append(q)
        return self.client(self.history)


_seen = {}  # ponytail: deliberately unbounded, this is the leak the test finds


def handle(req_id):
    _seen[req_id] = bytearray(1000)  # a fresh 1 KB buffer per request
    return len(_seen)


def top_growth(fn, n):
    tracemalloc.start()
    before = tracemalloc.take_snapshot()
    for i in range(n):
        fn(i)
    after = tracemalloc.take_snapshot()
    tracemalloc.stop()
    stats = after.compare_to(before, "lineno")
    return stats[0]  # biggest growth, by source line

// Structural typing: compatibility is by shape, so a value typed Point can carry extra keys at runtime.
// Run the test: node --experimental-strip-types interviews/coframe_builds/ts-structural.test.ts

export interface Point { x: number; y: number }

export function norm(p: Point): number { return Math.hypot(p.x, p.y); }

// The parameter says Point; the JSON says whatever the object really holds.
export function serialise(p: Point): string { return JSON.stringify(p); }

// Copy the declared keys when the shape must be exact (logs, storage, a prompt).
export function exactPoint(p: Point): Point { return { x: p.x, y: p.y }; }

// Object.keys is string[] by design; cast once, in a helper, only for objects you own.
export function keysOf<T extends object>(o: T): (keyof T)[] { return Object.keys(o) as (keyof T)[]; }

// Never called: tsc checks these lines (each @ts-expect-error must be a real error).
export function typeDemos(): void {
  const p3 = { x: 1, y: 2, z: 3 };
  const ok: Point = p3;                    // fine: not a fresh literal, no excess property check
  // @ts-expect-error excess property check fires only on a fresh object literal
  const bad: Point = { x: 1, y: 2, z: 3 };

  interface Opts { retries?: number; timeoutMs?: number }
  const typo = { retry: 3 };
  // @ts-expect-error weak type detection: all-optional target, no property in common
  const w: Opts = typo;

  const ks = Object.keys(ok);              // string[]
  // @ts-expect-error a string cannot index Point
  ok[ks[0]!];

  class Usd { cents = 0 }
  class Eur { cents = 0 }
  const e: Eur = new Usd();                // compiles: same shape, names do not matter

  class A { private k = 0 }
  class B { private k = 0 }
  // @ts-expect-error private members make classes nominal
  const b: B = new A();
  void [bad, w, e, b];
}

// any, unknown and never: unknown at every boundary, never for code that cannot return.
// Run the test: node --experimental-strip-types interviews/coframe_builds/ts-unknown.test.ts

// JSON.parse returns any; wrap it so callers get unknown and must narrow.
export function parseJson(s: string): unknown { return JSON.parse(s); }

// Anything can be thrown (strings included), so normalise before reading .message.
export function toError(e: unknown): Error {
  return e instanceof Error ? e : new Error(String(e));
}

export function fail(msg: string): never { throw new Error(msg); }

// any is contagious: everything read from it is any, so nothing below is checked.
export function countFromAny(s: string): number {
  const a: any = JSON.parse(s);
  const n: number = a.count;               // compiles even when count is missing
  return n + 1;
}

// unknown forces the check before use.
export function countFromUnknown(s: string): number {
  const u = parseJson(s);
  if (typeof u === "object" && u !== null && "count" in u && typeof u.count === "number") return u.count + 1;
  return fail("count missing");
}

export function typeDemos(): void {
  const u: unknown = parseJson("{}");
  // @ts-expect-error unknown cannot be used without narrowing
  u.foo;
  const x: string = Math.random() > 2 ? "a" : fail("nope"); // never is assignable to every type
  try { fail("x"); } catch (e) {
    // @ts-expect-error with strict, the catch variable is unknown
    e.message;
  }
  void x;
}

// Narrowing: a discriminated union of agent stream events, an exhaustive switch, and a guard that lies.
// Run the test: node --experimental-strip-types interviews/coframe_builds/ts-narrowing.test.ts

export type Ev =
  | { type: "text"; delta: string }
  | { type: "tool_call"; id: string; name: string; args: unknown }
  | { type: "done"; reason: "stop" | "length" };

export function assertNever(v: never): never {
  throw new Error("unhandled event " + JSON.stringify(v));
}

// Add a member to Ev and the default branch stops compiling: a to-do list from the compiler.
// At runtime the same branch catches an event a newer server sent that this build does not know.
export function render(e: Ev): string {
  switch (e.type) {
    case "text": return e.delta;
    case "tool_call": return `[${e.name}]`;
    case "done": return e.reason === "length" ? " (cut off)" : "";
    default: return assertNever(e);
  }
}

// A type predicate is an unchecked promise: this one only checks the tag, and tsc believes it.
export function isTextLoose(v: unknown): v is { type: "text"; delta: string } {
  return typeof v === "object" && v !== null && "type" in v && v.type === "text";
}

// An assertion function narrows the caller's variable after it returns.
export function assertString(v: unknown): asserts v is string {
  if (typeof v !== "string") throw new TypeError("expected a string, got " + typeof v);
}

export function typeDemos(): void {
  const xs = [1, undefined, 2].filter((x) => x !== undefined);
  const n: number[] = xs;                  // inferred as number[] since TS 5.5
  function f(v: string | number | Date | null): string {
    if (v === null) return "null";
    if (typeof v === "string") return v.toUpperCase();
    if (v instanceof Date) return v.toISOString();
    return v.toFixed(2);                   // v is number here
  }
  function g(e: Ev): string {
    switch (e.type) {
      case "text": return e.delta;
      case "done": return e.reason;
      // @ts-expect-error tool_call is not handled, so e is not never
      default: return assertNever(e);
    }
  }
  void [n, f, g];
}

// Generics and mapped types: a tool registry where a missing handler is a compile error, plus type-level checks.
// Run the test: node --experimental-strip-types interviews/coframe_builds/ts-generics.test.ts

// Each tool owns a parser from untrusted input to its args (zod schemas in real code).
function obj(raw: unknown): Record<string, unknown> {
  if (typeof raw !== "object" || raw === null) throw new TypeError("args must be an object");
  return raw as Record<string, unknown>;
}
const tools = {
  search: (raw: unknown) => {
    const q = obj(raw).query;
    if (typeof q !== "string") throw new TypeError("query must be a string");
    return { query: q };
  },
  run_tests: (raw: unknown) => {
    const { path, watch = false } = obj(raw);
    if (typeof path !== "string" || typeof watch !== "boolean") throw new TypeError("bad run_tests args");
    return { path, watch };
  },
};
type Tools = typeof tools;
export type ArgMap = { [K in keyof Tools]: ReturnType<Tools[K]> };
export type ToolCall = { [K in keyof ArgMap]: { name: K; args: ArgMap[K] } }[keyof ArgMap];
type Handlers = { [K in keyof ArgMap]: (args: ArgMap[K]) => Promise<string> };

// Leave out run_tests here and this object stops compiling.
const handlers: Handlers = {
  search: async ({ query }) => `searched ${query}`,
  run_tests: async ({ path, watch }) => `${path} watch=${watch}`,
};

export function isToolName(s: string): s is keyof Tools { return Object.hasOwn(tools, s); }

// Generic over K: TS relates handlers[name] to ArgMap[K]. One cast at the seam, where the parser runs.
export async function dispatch<K extends keyof Tools>(name: K, raw: unknown): Promise<string> {
  const args = tools[name](raw) as ArgMap[K];
  return handlers[name](args);
}

// Type-level tests: Expect<Equal<A, B>> fails to compile unless A and B are the same type.
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends (<T>() => T extends B ? 1 : 2) ? true : false;
type Expect<T extends true> = T;

export type ElementOf<T> = T extends readonly (infer E)[] ? E : never;
export type Unwrap<T> = T extends Promise<infer U> ? Unwrap<U> : T;
export type ToArr<T> = T extends unknown ? T[] : never;          // naked T: distributes over a union
export type NonDist<T> = [T] extends [unknown] ? T[] : never;     // wrapped: no distribution
export type Getters<T> = { [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K] };
export type ParseRoute<S extends string> =
  S extends `${string}:${infer P}/${infer Rest}` ? P | ParseRoute<`/${Rest}`>
  : S extends `${string}:${infer P}` ? P : never;

export function over(x: string): string;
export function over(x: number): number;
export function over(x: string | number): string | number { return x; }

export type Checks = [
  Expect<Equal<ElementOf<string[]>, string>>,
  Expect<Equal<Unwrap<Promise<Promise<number>>>, number>>,
  Expect<Equal<ToArr<string | number>, string[] | number[]>>,
  Expect<Equal<NonDist<string | number>, (string | number)[]>>,
  Expect<Equal<Getters<{ name: string }>, { getName: () => string }>>,
  Expect<Equal<ParseRoute<"/users/:id/jobs/:jobId">, "id" | "jobId">>,
  Expect<Equal<ReturnType<typeof over>, number>>,            // overloads: the last one wins
  Expect<Equal<ToolCall, { name: "search"; args: { query: string } } | { name: "run_tests"; args: { path: string; watch: boolean } }>>,
];

export function typeDemos(call: ToolCall): void {
  // @ts-expect-error correlated union: TS cannot tie call.name to call.args across the union
  handlers[call.name](call.args);

  function tuple<const T extends readonly unknown[]>(xs: T): T { return xs; }  // TS 5.0
  const t: readonly ["a", 1] = tuple(["a", 1]);
  function pick<T extends string>(opts: T[], def?: NoInfer<T>): T | undefined { return def ?? opts[0]; } // TS 5.4
  // @ts-expect-error "c" is not one of the inferred options
  pick(["a", "b"], "c");
  void t;
}

// satisfies vs as, as const, readonly and branded ids: what each checks at compile time and what survives to runtime.
// Run the test: node --experimental-strip-types interviews/coframe_builds/ts-satisfies.test.ts

// satisfies checks the shape and keeps the literal keys, so a typo in a key is a compile error.
export const MODELS = {
  fast: { id: "small-1", maxTokens: 1024 },
  heavy: { id: "large-1", maxTokens: 8192 },
} satisfies Record<string, { id: string; maxTokens: number }>;
export type ModelKey = keyof typeof MODELS;                  // "fast" | "heavy"

// as const: a runtime array AND a union type, no enum needed. It does not freeze anything.
export const TOOL_NAMES = ["search", "fetch"] as const;
export type ToolName = (typeof TOOL_NAMES)[number];          // "search" | "fetch"
export function isToolName(s: string): s is ToolName {
  return (TOOL_NAMES as readonly string[]).includes(s);      // TOOL_NAMES.includes(s) does not compile
}

// Branded id: a string at runtime, a distinct type at compile time. The only cast lives here, behind a check.
type Brand<T, B extends string> = T & { readonly __brand: B };
export type RunId = Brand<string, "RunId">;
export type TenantId = Brand<string, "TenantId">;
export function RunId(s: string): RunId {
  if (!/^run_[a-z0-9]+$/.test(s)) throw new TypeError(`not a run id: ${s}`);
  return s as RunId;
}
export function cancelRun(id: RunId): string { return `cancelled ${id}`; }

// as is an assertion, not a conversion: the value is whatever JSON.parse produced.
export function retriesPlusOne(json: string): unknown {
  const cfg = JSON.parse(json) as { retries: number };
  return cfg.retries + 1;
}

// readonly is one-way and compile-time only: the original alias can still mutate.
export function readonlyAlias(): number {
  const arr = [1, 2];
  const ro: readonly number[] = arr;
  arr.push(3);
  return ro.length;
}

export function typeDemos(t: TenantId): void {
  const annotated: Record<string, { id: string; maxTokens: number }> = MODELS;
  const m = annotated.fsat;                // compiles: the annotation widened keys to string
  // @ts-expect-error satisfies kept the keys, so the typo is caught
  MODELS.fsat;
  // @ts-expect-error a plain string is not a RunId
  cancelRun("run_1");
  // @ts-expect-error a TenantId is not a RunId
  cancelRun(t);
  // @ts-expect-error string is not assignable to the element union
  TOOL_NAMES.includes("x" as string);
  const ro: readonly number[] = [1];
  // @ts-expect-error push does not exist on a readonly array
  ro.push(2);
  const lie = { a: 1 } as unknown as { b: string }; // double cast compiles: a review red flag
  void [m, lie];
}

// Where the type system is unsound on purpose: method bivariance, array covariance, narrowing kept across calls.
// Run the test: node --experimental-strip-types interviews/coframe_builds/ts-strict.test.ts
// Typecheck with strict, noUncheckedIndexedAccess and exactOptionalPropertyTypes on.

export class Animal { name = "a" }
export class Dog extends Animal { bark(): string { return "woof"; } }

interface MethodStyle<T> { handle(x: T): string }      // method syntax: parameters stay bivariant
interface PropStyle<T> { handle: (x: T) => string }     // function-typed property: checked contravariantly

const dogMethod: MethodStyle<Dog> = { handle: (d) => d.bark() };
export const animalMethod: MethodStyle<Animal> = dogMethod; // compiles, and is wrong

// Arrays are covariant: a Dog[] seen as Animal[] accepts any Animal.
export function covariantArrays(): string {
  const dogs: Dog[] = [];
  const animals: Animal[] = dogs;
  animals.push(new Animal());
  return dogs[0]!.bark();
}

// Narrowing on a property survives a call that changes it: tsc assumes calls do not mutate.
export function narrowingAcrossCalls(): number {
  const box: { v: string | null } = { v: "x" };
  const clear = () => { box.v = null; };
  if (box.v !== null) {
    clear();
    return box.v.length;                   // compiles, throws
  }
  return 0;
}

export function typeDemos(): void {
  const dogProp: PropStyle<Dog> = { handle: (d) => d.bark() };
  // @ts-expect-error strictFunctionTypes: a Dog handler cannot stand in for an Animal handler
  const animalProp: PropStyle<Animal> = dogProp;

  const counts: Record<string, number> = {};
  // @ts-expect-error noUncheckedIndexedAccess: counts["x"] is number | undefined
  counts["x"].toFixed();
  const first = [1, 2][0];
  const n: number = first ?? 0;            // the flag makes you handle the empty case

  interface Patch { title?: string }
  // @ts-expect-error exactOptionalPropertyTypes: absent is allowed, an explicit undefined is not
  const p: Patch = { title: undefined };

  const f: () => void = () => 42;          // compiles: a void-returning type accepts any return
  void [animalProp, n, p, f];
}

// Validation at the boundary: tool args from a model are unknown until parsed; failures become is_error tool results.
// Run the test: node --experimental-strip-types interviews/coframe_builds/ts-boundary.test.ts
import { toError } from "./ts-unknown.ts";

export type Result<T, E = string> = { ok: true; value: T } | { ok: false; error: E };
export const ok = <T>(value: T): Result<T, never> => ({ ok: true, value });
export const err = <E>(error: E): Result<never, E> => ({ ok: false, error });

// In real code this is z.object({ query: z.string().min(1), limit: z.number().int().min(1).max(50).default(10) })
// with type SearchArgs = z.infer<typeof SearchArgs>. Hand-written here (standard library only); stops at the first problem.
export type SearchArgs = { query: string; limit: number };
export function parseSearchArgs(raw: unknown): Result<SearchArgs> {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) return err("arguments must be an object");
  const { query, limit = 10 } = raw as { query?: unknown; limit?: unknown };
  if (typeof query !== "string" || query.length === 0) return err("query: expected a non-empty string");
  if (typeof limit !== "number" || !Number.isInteger(limit) || limit < 1 || limit > 50)
    return err("limit: expected an integer from 1 to 50");
  return ok({ query, limit });             // a new object: unknown keys are stripped, like z.object
}

export type ToolResult = { type: "tool_result"; tool_use_id: string; content: string; is_error?: true };

// A tool failure is data for the model, not a crash of the loop.
export async function runSearchTool(
  id: string,
  input: unknown,
  run: (a: SearchArgs) => Promise<string>,
): Promise<ToolResult> {
  const parsed = parseSearchArgs(input);
  if (!parsed.ok) return { type: "tool_result", tool_use_id: id, content: `Invalid arguments: ${parsed.error}`, is_error: true };
  try {
    return { type: "tool_result", tool_use_id: id, content: await run(parsed.value) };
  } catch (e) {
    return { type: "tool_result", tool_use_id: id, content: toError(e).message, is_error: true };
  }
}

// Exercise: what runs when on the JS event loop (sync code, microtasks, a timer, an async function body).
// Run its test: node --experimental-strip-types interviews/coframe_builds/async-event-loop.test.ts

export async function order(): Promise<string[]> {
  const log: string[] = [];
  const done = new Promise<void>((r) => setTimeout(r, 5));
  setTimeout(() => log.push("timeout"), 0); // a macrotask: waits for every microtask
  Promise.resolve().then(() => log.push("then")); // a microtask, queued now
  queueMicrotask(() => log.push("microtask")); // a microtask, queued second
  async function af(): Promise<void> {
    log.push("af start"); // runs synchronously, at the call
    await null; // the rest is queued as a microtask, third
    log.push("af after await");
  }
  void af();
  log.push("sync");
  await done;
  return log;
}

// A promise is eager: the executor runs inside the constructor, before the caller continues.
export function eager(): string[] {
  const log: string[] = [];
  const p = new Promise<void>((resolve) => {
    log.push("executor");
    resolve();
  });
  log.push("after new Promise");
  void p;
  return log;
}

// Exercise: a promise is eager (the call starts the work); sequential awaits add up, Promise.all overlaps; forEach(async) waits for nothing.
// Run its test: node --experimental-strip-types interviews/coframe_builds/async-coroutines-promises.test.ts
import { setTimeout as sleep } from "node:timers/promises";

export async function call(name: string, log: string[], ms = 50): Promise<string> {
  log.push(`start ${name}`);
  await sleep(ms);
  return name;
}

export function eagerCall(): string[] {
  const log: string[] = [];
  const p = call("x", log); // the body already ran up to its first await
  const seen = [...log];
  void p;
  return seen;
}

export async function sequential(log: string[]): Promise<[string[], number]> {
  const t0 = performance.now();
  const out: string[] = [];
  for (const n of ["a", "b"]) out.push(await call(n, log));
  return [out, performance.now() - t0];
}

export async function parallel(log: string[]): Promise<[string[], number]> {
  const t0 = performance.now();
  const out = await Promise.all(["a", "b"].map((n) => call(n, log)));
  return [out, performance.now() - t0];
}

export function forEachAsync(): string[] {
  const done: string[] = [];
  ["a", "b"].forEach(async (n) => {
    await sleep(1);
    done.push(n);
  });
  return done; // returned before any callback finished
}

// Exercise: Promise.all, allSettled, race and any cancel nothing; a shared AbortController is how the losers stop.
// Run its test: node --experimental-strip-types interviews/coframe_builds/async-fan-out.test.ts
import { setTimeout as sleep } from "node:timers/promises";

export function work(ms: number, log: string[], fail = false, signal?: AbortSignal): Promise<number> {
  return sleep(ms, undefined, { signal }).then(
    () => {
      if (fail) throw new Error(`boom ${ms}`);
      log.push(`done ${ms}`);
      return ms;
    },
    (e: unknown) => {
      log.push(`aborted ${ms}`);
      throw e;
    },
  );
}

// Promise.all rejects on the first rejection; the other promise keeps running.
export async function all(log: string[]): Promise<string> {
  try {
    await Promise.all([work(5, log, true), work(30, log)]);
    return "fulfilled";
  } catch (e) {
    return (e as Error).message;
  }
}

// Fail fast and actually stop the rest: one signal for the group, aborted on the first failure.
export async function allOrAbort(log: string[]): Promise<string> {
  const ac = new AbortController();
  const tasks = [work(5, log, true, ac.signal), work(30, log, false, ac.signal)].map((p) =>
    p.catch((e: unknown) => {
      ac.abort(e);
      throw e;
    }),
  );
  const settled = await Promise.allSettled(tasks); // wait for every child before leaving
  const first = settled.find((s) => s.status === "rejected");
  return first ? (ac.signal.reason as Error).message : "fulfilled";
}

export async function settled(): Promise<string[]> {
  const r = await Promise.allSettled([work(1, []), work(1, [], true)]);
  return r.map((s) => s.status);
}

export async function any(): Promise<string> {
  try {
    await Promise.any([work(1, [], true), work(2, [], true)]);
    return "fulfilled";
  } catch (e) {
    return e instanceof AggregateError ? `AggregateError ${e.errors.length}` : "other";
  }
}

// race: first to settle wins, rejection included. any: first to fulfil wins.
export async function raceVsAny(): Promise<[string, number]> {
  const r = await Promise.race([work(1, [], true), work(10, [])]).catch((e: Error) => e.message);
  const a = await Promise.any([work(1, [], true), work(10, [])]);
  return [String(r), a];
}

// Exercise: cancellation in JS is a signal you pass down: AbortController, AbortSignal.timeout, AbortSignal.any, and reading the reason.
// Run its test: node --experimental-strip-types interviews/coframe_builds/async-cancellation.test.ts
import { setTimeout as sleep } from "node:timers/promises";

// One deadline plus the caller's stop button, flowing into every awaited call.
export async function callModel(ms: number, user: AbortSignal, deadlineMs: number): Promise<string> {
  const signal = AbortSignal.any([user, AbortSignal.timeout(deadlineMs)]);
  try {
    await sleep(ms, undefined, { signal }); // stands in for fetch(url, { signal })
    return "ok";
  } catch (e) {
    if (!signal.aborted) throw e;
    const r = signal.reason; // the source signal's reason: a TimeoutError, or what the user passed
    return r instanceof DOMException && r.name === "TimeoutError" ? "timed out" : `stopped: ${(r as Error).message}`;
  }
}

// A loop that does its own work must check the signal itself: cancellation is cooperative.
export async function steps(n: number, signal: AbortSignal, log: string[]): Promise<void> {
  for (let i = 0; i < n; i++) {
    signal.throwIfAborted();
    log.push(`step ${i}`);
    await sleep(5);
  }
}

// Promise.race against a timer gives up waiting; the work itself carries on.
export async function raceTimeout(log: string[]): Promise<string> {
  const slow = sleep(30).then(() => log.push("slow work finished"));
  const timer = sleep(5).then(() => "timeout");
  const r = await Promise.race([slow.then(() => "done"), timer]);
  await slow;
  return r;
}

// Exercise: CPU work on the main thread delays every timer and request; a worker thread keeps the loop free.
// Run its test: node --experimental-strip-types interviews/coframe_builds/async-blocking.test.ts
import { Worker } from "node:worker_threads";

function spin(ms: number): void {
  const end = Date.now() + ms;
  while (Date.now() < end) {} // stands in for parsing a huge trace or diffing big files
}

// How late does a 0 ms timer fire while the main thread is busy?
export function timerLateness(busyMs: number): Promise<number> {
  const t0 = performance.now();
  const p = new Promise<number>((r) => setTimeout(() => r(performance.now() - t0), 0));
  spin(busyMs);
  return p;
}

// The same CPU work in a worker thread: the main thread keeps ticking meanwhile.
export function spinInWorker(ms: number): Promise<number> {
  const src = `const { parentPort, workerData } = require("node:worker_threads");
const end = Date.now() + workerData; while (Date.now() < end) {}
parentPort.postMessage(workerData);`;
  return new Promise((resolve, reject) => {
    const w = new Worker(src, { eval: true, workerData: ms });
    w.once("message", resolve);
    w.once("error", reject);
  });
}

// Exercise: a hand p-limit, a pull-based async generator, and a Web Stream whose pull() stops at the highWaterMark.
// Run its test: node --experimental-strip-types interviews/coframe_builds/async-backpressure.test.ts

// p-limit in ten lines: at most n functions running; the waiting queue itself is unbounded.
export function limiter(n: number) {
  let running = 0;
  const waiting: (() => void)[] = [];
  return async <T>(fn: () => Promise<T>): Promise<T> => {
    while (running >= n) await new Promise<void>((r) => waiting.push(r));
    running++;
    try {
      return await fn();
    } finally {
      running--;
      waiting.shift()?.();
    }
  };
}

// An async generator only runs when the consumer asks for the next value.
export async function* produce(log: string[]): AsyncGenerator<number> {
  for (let i = 0; i < 100; i++) {
    log.push(`made ${i}`);
    yield i;
  }
}

// A ReadableStream calls pull() only while desiredSize (highWaterMark minus queued) is above zero.
export function counted(highWaterMark: number): { stream: ReadableStream<number>; pulls: () => number } {
  let pulls = 0;
  const stream = new ReadableStream<number>(
    { pull(c) { c.enqueue(pulls++); } },
    new CountQueuingStrategy({ highWaterMark }),
  );
  return { stream, pulls: () => pulls };
}

// Exercise: retry with full jitter and an abortable sleep; parse an SSE body with for await, and stop the upstream on break.
// Run its test: node --experimental-strip-types interviews/coframe_builds/async-retries-streaming.test.ts
import { setTimeout as sleep } from "node:timers/promises";

export interface RetryOpts {
  retries: number;
  baseMs: number;
  maxMs: number;
  signal?: AbortSignal;
  shouldRetry?: (e: unknown) => boolean;
  random?: () => number;
}

export async function retry<T>(fn: (attempt: number) => Promise<T>, o: RetryOpts): Promise<T> {
  const rand = o.random ?? Math.random;
  for (let attempt = 0; ; attempt++) {
    o.signal?.throwIfAborted();
    try {
      return await fn(attempt); // return await, so the catch below sees the rejection
    } catch (e) {
      if (attempt >= o.retries || (o.shouldRetry && !o.shouldRetry(e))) throw e;
      const cap = Math.min(o.maxMs, o.baseMs * 2 ** attempt);
      await sleep(rand() * cap, undefined, { signal: o.signal }); // full jitter, and Stop still works mid-wait
    }
  }
}

// Yield each event's data until [DONE]. Frames end at a blank line; several data lines join with a newline.
export async function* sseData(body: ReadableStream<Uint8Array>): AsyncGenerator<string> {
  let buf = "";
  let data: string[] = [];
  for await (const chunk of body.pipeThrough(new TextDecoderStream())) {
    buf += chunk;
    let i: number;
    while ((i = buf.indexOf("\n")) >= 0) {
      const line = buf.slice(0, i).replace(/\r$/, "");
      buf = buf.slice(i + 1);
      if (line === "") {
        if (data.length) {
          const d = data.join("\n");
          data = [];
          if (d === "[DONE]") return;
          yield d;
        }
      } else if (line.startsWith("data:")) {
        data.push(line.slice(5).replace(/^ /, ""));
      } // ":" lines are heartbeats
    }
  }
}

// Exercise: JS has no TaskGroup, so build the scope by hand: one AbortController, abort the rest on the first failure, wait for every child.
// Run its test: node --experimental-strip-types interviews/coframe_builds/async-structured.test.ts

export type Spawn = <T>(fn: (signal: AbortSignal) => Promise<T>) => Promise<T>;

export async function scope<R>(body: (spawn: Spawn, signal: AbortSignal) => Promise<R>, parent?: AbortSignal): Promise<R> {
  const ac = new AbortController();
  const onParent = () => ac.abort(parent?.reason); // Stop from above reaches every child
  parent?.addEventListener("abort", onParent, { once: true });
  const children: Promise<unknown>[] = [];
  let failed: { e: unknown } | undefined;
  const fail = (e: unknown) => {
    if (failed) return;
    failed = { e };
    ac.abort(e); // the first failure stops the siblings
  };
  const spawn: Spawn = (fn) => {
    const p = fn(ac.signal);
    children.push(p.catch(fail));
    return p;
  };
  let result: R | undefined;
  try {
    result = await body(spawn, ac.signal);
  } catch (e) {
    fail(e);
  }
  // ponytail: waits for children spawned so far; a child that spawns after this point is not tracked
  await Promise.allSettled(children); // no child outlives the scope
  parent?.removeEventListener("abort", onParent); // no listener leak on a long-lived signal
  if (parent?.aborted) throw parent.reason;
  if (failed) throw failed.e;
  return result as R;
}

