      return new Promise((_, reject) => {
        if (!opts.ignoreAbort) signal.addEventListener("abort", () => reject(signal.reason), { once: true });
      });
    }
    return Promise.resolve(replies[Math.min(calls.length, replies.length) - 1]);
  };
  return { model, calls };
