# Exercise: a durable step runner. Each step's result is checkpointed by (run id, step name); after a crash a rerun skips finished steps, and side effects carry an idempotency key.
# Run the test: python interviews/coframe_builds/builds-durable-runner_test.py
import json
import sqlite3


class Runner:
    """Checkpoints in SQLite here; in production the same two columns live in Postgres."""

    def __init__(self, db):
        self.db = db
        db.execute(
            "create table if not exists steps("
            " run text, step text, status text, out text,"
            " primary key (run, step))"
        )

    def _get(self, run, name):
        return self.db.execute("select status, out from steps where run=? and step=?", (run, name)).fetchone()

    def _put(self, run, name, status, out=None):
        self.db.execute(
            "insert into steps values (?,?,?,?) on conflict(run, step) do update set status=excluded.status, out=excluded.out",
            (run, name, status, None if out is None else json.dumps(out)),
        )
        self.db.commit()                                   # durable before the next step starts

    def step(self, run, name, fn):
        """Pure or repeatable work (an LLM call you are happy to pay for twice). Replays the recorded result."""
        row = self._get(run, name)
        if row and row[0] == "done":
            return json.loads(row[1])
        out = fn()
        self._put(run, name, "done", out)
        return out

    def effect(self, run, name, fn):
        """A side effect. fn receives the idempotency key and must pass it downstream.
        'started' is written first, so after a crash we know this call was in flight."""
        row = self._get(run, name)
        if row and row[0] == "done":
            return json.loads(row[1])
        self._put(run, name, "started")
        out = fn("%s:%s" % (run, name))                      # same key on every attempt of this step
        self._put(run, name, "done", out)
        return out

    def in_flight(self, run):
        """Steps that started and never recorded a result: the crash window."""
        return [r[0] for r in self.db.execute("select step from steps where run=? and status='started'", (run,))]

// Exercise: a durable step runner. Each step's result is checkpointed by (run id, step name); after a crash a rerun skips finished steps, and side effects carry an idempotency key.
// Run the test: node --experimental-strip-types interviews/coframe_builds/builds-durable-runner.test.ts

type Row = { status: "started" | "done"; out?: unknown };

// The store holds JSON strings, as a Postgres row would: what comes back is a copy, never the live object.
export type Store = Map<string, string>;

export class Runner {
  store: Store;
  constructor(store: Store) { this.store = store; }

  private get(run: string, name: string): Row | undefined {
    const s = this.store.get(`${run}\u0000${name}`);
    return s === undefined ? undefined : (JSON.parse(s) as Row);
  }

  private put(run: string, name: string, row: Row): void {
    this.store.set(`${run}\u0000${name}`, JSON.stringify(row));     // in production: an awaited upsert
  }

  /** Pure or repeatable work (an LLM call you are happy to pay for twice). Replays the recorded result. */
  async step<T>(run: string, name: string, fn: () => Promise<T>): Promise<T> {
    const row = this.get(run, name);
    if (row?.status === "done") return row.out as T;
    const out = await fn();
    this.put(run, name, { status: "done", out });
    return out;
  }

  /** A side effect. fn receives the idempotency key and must send it downstream. */
  async effect<T>(run: string, name: string, fn: (key: string) => Promise<T>): Promise<T> {
    const row = this.get(run, name);
    if (row?.status === "done") return row.out as T;
    this.put(run, name, { status: "started" });                     // after a crash we can see it was in flight
    const out = await fn(`${run}:${name}`);                         // the same key on every attempt
    this.put(run, name, { status: "done", out });
    return out;
  }

  inFlight(run: string): string[] {
    const prefix = `${run}\u0000`;
    return [...this.store].filter(([k, v]) => k.startsWith(prefix) && (JSON.parse(v) as Row).status === "started")
      .map(([k]) => k.slice(prefix.length));
  }
}

// Tests for builds-durable-runner.ts: crash a run at each point, restart with only the store, count the side effects.
// Run: node --experimental-strip-types interviews/coframe_builds/builds-durable-runner.test.ts
import assert from "node:assert/strict";
import { Runner, type Store } from "./builds-durable-runner.ts";

class Crash extends Error {}

class Repo {                                    // a fake GitHub that dedupes on the idempotency key
  prs: string[] = [];
  byKey = new Map<string, number>();
  async openPr(branch: string, key?: string): Promise<number> {
    if (key !== undefined && this.byKey.has(key)) return this.byKey.get(key)!;
    this.prs.push(branch);
    if (key !== undefined) this.byKey.set(key, this.prs.length);
    return this.prs.length;
  }
}

type Crashes = "before_pr" | "after_pr_before_record" | undefined;

async function workflow(r: Runner, run: string, repo: Repo, llm: string[], crashAt?: Crashes, sendKey = true) {
  const plan = await r.step(run, "plan", async () => { llm.push("plan"); return ["edit header", "run tests"]; });
  for (const [i, task] of plan.entries()) {
    await r.step(run, `tool:${i}`, async () => { llm.push(task); return `ok: ${task}`; });
  }
  if (crashAt === "before_pr") throw new Crash();
  return r.effect(run, "open_pr", async (key) => {
    const n = await repo.openPr(`agent/${run}`, sendKey ? key : undefined);
    if (crashAt === "after_pr_before_record") throw new Crash();   // the PR exists, the checkpoint does not
    return n;
  });
}

const store: Store = new Map();
const restart = () => new Runner(store);         // a new process: only the store survives

// 1. Crash before the side effect: the restart skips plan and both tool steps.
{
  const repo = new Repo(), llm: string[] = [];
  await assert.rejects(workflow(restart(), "r1", repo, llm, "before_pr"), Crash);
  assert.equal(await workflow(restart(), "r1", repo, llm), 1);
  assert.deepEqual(llm, ["plan", "edit header", "run tests"]);
  assert.deepEqual(repo.prs, ["agent/r1"]);
}

// 2. The in-flight problem, solved by the key.
{
  const repo = new Repo(), llm: string[] = [];
  await assert.rejects(workflow(restart(), "r2", repo, llm, "after_pr_before_record"), Crash);
  assert.deepEqual(restart().inFlight("r2"), ["open_pr"]);
  assert.equal(await workflow(restart(), "r2", repo, llm), 1);
  assert.deepEqual(repo.prs, ["agent/r2"]);
  assert.deepEqual(restart().inFlight("r2"), []);
}

// 3. The same crash with no key: two PRs.
{
  const repo = new Repo(), llm: string[] = [];
  await assert.rejects(workflow(restart(), "r3", repo, llm, "after_pr_before_record", false), Crash);
  await workflow(restart(), "r3", repo, llm, undefined, false);
  assert.deepEqual(repo.prs, ["agent/r3", "agent/r3"]);
}

// 4. A finished run replays from checkpoints; results come back as copies.
{
  const repo = new Repo(), llm: string[] = [];
  assert.equal(await workflow(restart(), "r1", repo, llm), 1);
  assert.deepEqual(llm, []);
  const r = restart();
  const a = await r.step("r5", "obj", async () => ({ n: 1 }));
  a.n = 99;                                       // mutating the result must not change the checkpoint
  assert.deepEqual(await restart().step("r5", "obj", async () => ({ n: 2 })), { n: 1 });
}
console.log("builds-durable-runner.ts: all tests passed");

// Exercise: call a flaky, rate-limited model API for N items with bounded concurrency, a token bucket, retries with full jitter on retryable errors only, a per-call timeout, and cancellation of the rest when the caller gives up.
// Run the test: node --experimental-strip-types interviews/coframe_builds/builds-fanout.test.ts

/** 429, 5xx, a dropped connection. retryAfterMs carries the server's Retry-After. */
export class RetryableError extends Error {
  retryAfterMs?: number;
  constructor(msg: string, retryAfterMs?: number) { super(msg); this.retryAfterMs = retryAfterMs; }
}
/** 400, 401, a schema error: retrying sends the same bad request again. */
export class FatalError extends Error {}

export type Sleep = (ms: number, signal?: AbortSignal) => Promise<void>;
export type Result<R> = { ok: true; value: R } | { ok: false; error: unknown };

export const realSleep: Sleep = (ms, signal) => new Promise((resolve, reject) => {
  if (signal?.aborted) return reject(signal.reason);
  const t = setTimeout(() => { signal?.removeEventListener("abort", onAbort); resolve(); }, ms);
  const onAbort = () => { clearTimeout(t); reject(signal!.reason); };
  signal?.addEventListener("abort", onAbort, { once: true });
});

/** Reservation style: take() books a token now (tokens may go negative) and waits until it is due.
 *  No lock: the refill, check and booking run with no await in between, so nothing interleaves. */
export class TokenBucket {
  rate: number; burst: number; tokens: number; t: number;
  now: () => number; sleep: Sleep;
  constructor(ratePerSec: number, burst: number, now: () => number = () => performance.now(), sleep: Sleep = realSleep) {
    this.rate = ratePerSec / 1000; this.burst = burst; this.tokens = burst;
    this.now = now; this.sleep = sleep; this.t = now();
  }
  async take(signal?: AbortSignal): Promise<void> {
    const t = this.now();
    this.tokens = Math.min(this.burst, this.tokens + (t - this.t) * this.rate);
    this.t = t;
    this.tokens -= 1;
    if (this.tokens >= 0) return;
    try { await this.sleep(-this.tokens / this.rate, signal); }
    catch (e) { this.tokens += 1; throw e; }                      // give the booking back
  }
}

/** A semaphore in ten lines. Queued work that is aborted never runs. */
function limiter(n: number) {
  let running = 0;
  const queue: (() => void)[] = [];
  return async <T>(fn: () => Promise<T>): Promise<T> => {
    if (running >= n) await new Promise<void>((r) => queue.push(r));
    running++;
    try { return await fn(); } finally { running--; queue.shift()?.(); }
  };
}

const isTimeout = (e: unknown) => e instanceof DOMException && e.name === "TimeoutError";

export type FanOutOpts = {
  limit: number; bucket: TokenBucket; attempts?: number; baseMs?: number; capMs?: number;
  timeoutMs?: number; signal?: AbortSignal; sleep?: Sleep; rand?: () => number;
};

/** One result per item, in order. If the caller's signal aborts, in-flight calls see it, queued items
 *  never start, and the returned promise rejects with the caller's reason. */
export async function fanOut<T, R>(items: T[], call: (item: T, signal: AbortSignal) => Promise<R>,
  o: FanOutOpts): Promise<Result<R>[]> {
  const { attempts = 4, baseMs = 500, capMs = 8000, timeoutMs = 30000, sleep = realSleep, rand = Math.random } = o;
  const slot = limiter(o.limit);

  async function one(item: T): Promise<Result<R>> {
    for (let n = 0; ; n++) {
      let err: unknown;
      try {
        return await slot(async (): Promise<Result<R>> => {      // a slot only while calling, not while backing off
          o.signal?.throwIfAborted();                              // queued and the caller left: do not start
          await o.bucket.take(o.signal);                           // every attempt spends rate
          // Per-call deadline joined with the caller's signal. A ref'd timer, cleared when the call ends.
          const ac = new AbortController();
          const timer = setTimeout(() => ac.abort(new DOMException("call timed out", "TimeoutError")), timeoutMs);
          const signal = o.signal ? AbortSignal.any([o.signal, ac.signal]) : ac.signal;
          try { return { ok: true, value: await call(item, signal) }; } finally { clearTimeout(timer); }
        });
      } catch (e) {
        if (o.signal?.aborted) throw o.signal.reason;              // the caller gave up: stop everything
        if (!(e instanceof RetryableError || isTimeout(e))) return { ok: false, error: e };
        err = e;
      }
      if (n === attempts - 1) return { ok: false, error: err };
      const ra = err instanceof RetryableError ? err.retryAfterMs : undefined;
      await sleep(ra ?? rand() * Math.min(capMs, baseMs * 2 ** n), o.signal);     // full jitter, abortable
    }
  }

  // Promise.all, not allSettled: per-item failures are already values, so a rejection here means the caller aborted.
  return Promise.all(items.map(one));
}

// Tests for builds-fanout.ts: a fake API and a fake clock; only the per-call and caller timeouts use real (tiny) time.
// Run: node --experimental-strip-types interviews/coframe_builds/builds-fanout.test.ts
import assert from "node:assert/strict";
import { fanOut, FatalError, RetryableError, TokenBucket, type Sleep } from "./builds-fanout.ts";

function clock() {
  const slept: number[] = [];
  const sleep: Sleep = async (ms) => { slept.push(Math.round(ms * 1000) / 1000); await Promise.resolve(); };
  return { slept, sleep, now: () => 0 };
}
const roomy = () => new TokenBucket(1e6, 1e6);
const hang = (signal: AbortSignal) => new Promise<never>((_, reject) =>
  signal.addEventListener("abort", () => reject(signal.reason), { once: true }));
const values = <R>(rs: { ok: boolean; value?: R }[]) => rs.map((r) => r.value);

// Concurrency is bounded.
{
  let inflight = 0, peak = 0;
  const work = async (x: number) => {
    inflight++; peak = Math.max(peak, inflight);
    for (let i = 0; i < 3; i++) await Promise.resolve();
    inflight--; return x * 2;
  };
  const rs = await fanOut([...Array(10).keys()], work, { limit: 3, bucket: roomy() });
  assert.deepEqual(values(rs), [...Array(10).keys()].map((x) => x * 2));
  assert.equal(peak, 3);
}

// Rate: burst 2, then one token per 200 ms at 5/s, booked in order.
{
  const c = clock();
  await fanOut([...Array(10).keys()], async (x) => x, { limit: 10, bucket: new TokenBucket(5, 2, c.now, c.sleep) });
  assert.deepEqual(c.slept, [200, 400, 600, 800, 1000, 1200, 1400, 1600]);
}

// Retryable twice then success; rand pinned to 1 shows the exponential ceiling.
{
  const c = clock(); let tries = 0;
  const flaky = async () => { if (++tries <= 2) throw new RetryableError("503"); return "ok"; };
  const rs = await fanOut(["a"], flaky, { limit: 1, bucket: roomy(), sleep: c.sleep, rand: () => 1 });
  assert.deepEqual(values(rs), ["ok"]);
  assert.deepEqual(c.slept, [500, 1000]);
}

// Jitter scales the ceiling, the cap holds, exhausting attempts returns the last error.
{
  const c = clock();
  const [r] = await fanOut(["a"], async () => { throw new RetryableError("503"); },
    { limit: 1, bucket: roomy(), attempts: 6, capMs: 2000, sleep: c.sleep, rand: () => 0.5 });
  assert.ok(!r.ok && r.error instanceof RetryableError);
  assert.deepEqual(c.slept, [250, 500, 1000, 1000, 1000]);
}

// Retry-After wins over the computed delay.
{
  const c = clock(); let tries = 0;
  const limited = async () => { if (++tries === 1) throw new RetryableError("429", 7000); return "ok"; };
  await fanOut(["a"], limited, { limit: 1, bucket: roomy(), sleep: c.sleep });
  assert.deepEqual(c.slept, [7000]);
}

// Fatal is never retried; one bad item does not sink the rest.
{
  const calls: string[] = [];
  const mixed = async (x: string) => { calls.push(x); if (x === "bad") throw new FatalError("400"); return x; };
  const rs = await fanOut(["a", "bad", "b"], mixed, { limit: 2, bucket: roomy() });
  assert.deepEqual([rs[0].ok, rs[1].ok, rs[2].ok], [true, false, true]);
  assert.equal(calls.filter((x) => x === "bad").length, 1);
}

// Per-call timeout: the first attempt hangs, the second answers.
{
  const c = clock(); let tries = 0;
  const hangsOnce = (_: string, signal: AbortSignal) => (++tries === 1 ? hang(signal) : Promise.resolve("ok"));
  const rs = await fanOut(["a"], hangsOnce, { limit: 1, bucket: roomy(), timeoutMs: 10, sleep: c.sleep });
  assert.deepEqual(values(rs), ["ok"]);
  assert.equal(c.slept.length, 1);
}

// The caller gives up: in-flight calls see the abort, queued items never start, the promise rejects.
{
  const started: number[] = [], aborted: number[] = [];
  const forever = (x: number, signal: AbortSignal) => {
    started.push(x);
    return hang(signal).catch((e) => { aborted.push(x); throw e; });
  };
  const user = new AbortController();
  setTimeout(() => user.abort(new Error("user left")), 20);
  await assert.rejects(fanOut([0, 1, 2, 3, 4], forever, { limit: 2, bucket: roomy(), signal: user.signal }), /user left/);
  await new Promise((r) => setTimeout(r, 5));                  // let queued items drain their slots
  assert.deepEqual(started, [0, 1]);
  assert.deepEqual(aborted.sort(), [0, 1]);
}

// A cancelled wait on the bucket gives its booking back.
{
  const b = new TokenBucket(1, 1, () => 0, (_ms, signal) => hang(signal!));
  await b.take();
  const ac = new AbortController();
  const waiting = b.take(ac.signal);
  assert.equal(b.tokens, -1);
  ac.abort();
  await assert.rejects(waiting);
  assert.equal(b.tokens, 0);
}
console.log("builds-fanout.ts: all tests passed");

# Exercise: parse a streamed server-sent-events response incrementally (chunks split anywhere, multi-line data, [DONE]), assemble text and tool-call deltas, and stop cleanly on timeout or user cancel.
# Run the test: python interviews/coframe_builds/builds-sse_test.py
import asyncio
import codecs
import contextlib
import json
import re
from dataclasses import dataclass, field

LINE_END = re.compile(r"\r\n|\r|\n")


@dataclass
class Event:
    event: str
    data: str
    id: str | None = None


class SSEParser:
    """Feed it bytes as they arrive; it returns the events completed so far."""

    def __init__(self):
        self.dec = codecs.getincrementaldecoder("utf-8")()   # holds half of a multi-byte character
        self.buf, self.data, self.event, self.last_id = "", [], "", None

    def feed(self, chunk: bytes) -> list[Event]:
        self.buf += self.dec.decode(chunk)
        out = []
        while m := LINE_END.search(self.buf):
            if m.group() == "\r" and m.end() == len(self.buf):
                break                                       # maybe the first half of \r\n: wait
            line, self.buf = self.buf[:m.start()], self.buf[m.end():]
            if ev := self._line(line):
                out.append(ev)
        return out

    def _line(self, line):
        if line == "":                                      # a blank line ends the event
            if not self.data:
                self.event = ""
                return None
            ev = Event(self.event or "message", "\n".join(self.data), self.last_id)
            self.data, self.event = [], ""
            return ev
        if line.startswith(":"):
            return None                                     # comment, often a keep-alive ping
        name, _, value = line.partition(":")
        value = value[1:] if value.startswith(" ") else value
        if name == "data":
            self.data.append(value)
        elif name == "event":
            self.event = value
        elif name == "id":
            self.last_id = value                            # resume point for Last-Event-ID
        return None


@dataclass
class Reply:
    text: str = ""
    calls: dict = field(default_factory=dict)              # index -> {id, name, args}
    status: str = "streaming"                               # done | truncated | timeout | cancelled

    def add(self, payload):
        """OpenAI-style chunk: choices[0].delta has content and/or tool_calls fragments."""
        delta = payload["choices"][0].get("delta", {})
        self.text += delta.get("content") or ""
        for tc in delta.get("tool_calls") or []:
            c = self.calls.setdefault(tc["index"], {"id": None, "name": "", "args": ""})
            c["id"] = tc.get("id") or c["id"]
            fn = tc.get("function") or {}
            c["name"] += fn.get("name") or ""
            c["args"] += fn.get("arguments") or ""         # JSON text arrives in pieces: parse only at the end

    def tool_calls(self):
        """Only a finished stream yields calls to execute; arguments must parse as a JSON object."""
        if self.status != "done":
            return []
        out = []
        for _, c in sorted(self.calls.items()):
            try:
                args = json.loads(c["args"] or "{}")
            except json.JSONDecodeError:
                args = None
            out.append({"id": c["id"], "name": c["name"], "args": args if isinstance(args, dict) else None})
        return out


async def consume(source, reply, *, deadline_s):
    """Read an async iterator of bytes into reply. A user cancel is task.cancel(): reply keeps the partial text."""
    parser = SSEParser()
    try:
        async with asyncio.timeout(deadline_s):
            # aclosing: leaving an async for early does NOT close an async generator in Python
            # (unlike JavaScript's for await); this closes the upstream on [DONE], error or cancel.
            async with contextlib.aclosing(source) as chunks:
                async for chunk in chunks:
                    for ev in parser.feed(chunk):
                        if ev.data == "[DONE]":
                            reply.status = "done"
                            return reply
                        reply.add(json.loads(ev.data))
        reply.status = "truncated"                          # the connection ended without [DONE]
    except TimeoutError:
        reply.status = "timeout"
    except asyncio.CancelledError:
        reply.status = "cancelled"
        raise                                               # never swallow a cancel
    return reply

// Exercise: parse a streamed server-sent-events response incrementally (chunks split anywhere, multi-line data, [DONE]), assemble text and tool-call deltas, and stop cleanly on timeout or user cancel.
// Run the test: node --experimental-strip-types interviews/coframe_builds/builds-sse.test.ts

export type SSEEvent = { event: string; data: string; id?: string };

export class SSEParser {
  private dec = new TextDecoder();          // { stream: true } below holds half of a multi-byte character
  private buf = "";
  private data: string[] = [];
  private event = "";
  private lastId: string | undefined;

  feed(chunk: Uint8Array): SSEEvent[] {
    this.buf += this.dec.decode(chunk, { stream: true });
    const out: SSEEvent[] = [];
    const re = /\r\n|\r|\n/g;
    let start = 0;
    for (let m = re.exec(this.buf); m; m = re.exec(this.buf)) {
      if (m[0] === "\r" && re.lastIndex === this.buf.length) break;   // maybe half of \r\n: wait
      const ev = this.line(this.buf.slice(start, m.index));
      if (ev) out.push(ev);
      start = re.lastIndex;
    }
    this.buf = this.buf.slice(start);
    return out;
  }

  private line(line: string): SSEEvent | undefined {
    if (line === "") {                                   // a blank line ends the event
      if (this.data.length === 0) { this.event = ""; return undefined; }
      const ev: SSEEvent = { event: this.event || "message", data: this.data.join("\n"), id: this.lastId };
      this.data = []; this.event = "";
      return ev;
    }
    if (line.startsWith(":")) return undefined;          // comment, often a keep-alive ping
    const i = line.indexOf(":");
    const name = i < 0 ? line : line.slice(0, i);
    let value = i < 0 ? "" : line.slice(i + 1);
    if (value.startsWith(" ")) value = value.slice(1);
    if (name === "data") this.data.push(value);
    else if (name === "event") this.event = value;
    else if (name === "id") this.lastId = value;         // resume point for Last-Event-ID
    return undefined;
  }
}

type Delta = { content?: string | null; tool_calls?: { index: number; id?: string; function?: { name?: string; arguments?: string } }[] };
export type ToolCall = { id: string | undefined; name: string; args: Record<string, unknown> | null };
export type Status = "streaming" | "done" | "truncated" | "timeout" | "cancelled";

export class Reply {
  text = "";
  calls = new Map<number, { id?: string; name: string; args: string }>();
  status: Status = "streaming";

  /** OpenAI-style chunk: choices[0].delta carries content and/or tool_calls fragments. */
  add(payload: { choices: { delta?: Delta }[] }): void {
    const delta = payload.choices[0]?.delta ?? {};
    this.text += delta.content ?? "";
    for (const tc of delta.tool_calls ?? []) {
      const c = this.calls.get(tc.index) ?? { name: "", args: "" };
      c.id = tc.id ?? c.id;
      c.name += tc.function?.name ?? "";
      c.args += tc.function?.arguments ?? "";            // JSON text in pieces: parse only at the end
      this.calls.set(tc.index, c);
    }
  }

  /** Only a finished stream yields calls to execute; arguments must parse as a JSON object. */
  toolCalls(): ToolCall[] {
    if (this.status !== "done") return [];
    return [...this.calls.entries()].sort(([a], [b]) => a - b).map(([, c]) => {
      let args: unknown = null;
      try { args = JSON.parse(c.args || "{}"); } catch { /* left null: send the error back to the model */ }
      const ok = typeof args === "object" && args !== null && !Array.isArray(args);
      return { id: c.id, name: c.name, args: ok ? (args as Record<string, unknown>) : null };
    });
  }
}

/** open(signal) is the fetch: it must honour the signal, so an abort rejects the pending read.
 *  The caller cancels with its own signal; the deadline is a ref'd timer joined to it. */
export async function consume(open: (signal: AbortSignal) => AsyncIterable<Uint8Array>, reply: Reply,
  o: { deadlineMs: number; signal?: AbortSignal }): Promise<Reply> {
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(new DOMException("stream deadline", "TimeoutError")), o.deadlineMs);
  const signal = o.signal ? AbortSignal.any([o.signal, ac.signal]) : ac.signal;
  const parser = new SSEParser();
  try {
    // break and return inside for await call the iterator's return(): the upstream closes on [DONE] too.
    for await (const chunk of open(signal)) {
      for (const ev of parser.feed(chunk)) {
        if (ev.data === "[DONE]") { reply.status = "done"; return reply; }
        reply.add(JSON.parse(ev.data));
      }
    }
    reply.status = "truncated";                          // the connection ended without [DONE]
  } catch (e) {
    if (!signal.aborted) throw e;                        // a real error (bad JSON, network): surface it
    reply.status = (signal.reason as Error)?.name === "TimeoutError" ? "timeout" : "cancelled";
  } finally {
    clearTimeout(timer);
  }
  return reply;
}

// Tests for builds-sse.ts: one recorded stream, cut at every chunk size, plus hang, cancel and truncation cases.
// Run: node --experimental-strip-types interviews/coframe_builds/builds-sse.test.ts
import assert from "node:assert/strict";
import { consume, Reply, SSEParser } from "./builds-sse.ts";

const chunk = (delta: object) => JSON.stringify({ choices: [{ delta }] });
const STREAM =
  ": keep-alive\n\n" +
  `id: 1\ndata: ${chunk({ content: "Naïve café " })}\n\n` +
  // one JSON payload over two data lines: joined with \n, which JSON reads as whitespace
  'data: {"choices": [{"delta":\ndata: {"content": "✓ ok"}}]}\n\n' +
  `data: ${chunk({ tool_calls: [{ index: 0, id: "call_1", function: { name: "search", arguments: '{"q": "ole' } }] })}\n\n` +
  `data: ${chunk({ tool_calls: [{ index: 0, function: { arguments: 'd 65"}' } }] })}\n\n` +
  "data: [DONE]\n\n" +
  `data: ${chunk({ content: "after done" })}\n\n`;
const enc = new TextEncoder();
const bytes = enc.encode(STREAM);

/** A fake fetch body: yields byte slices, can hang at the end, honours the signal, records closing. */
function source(data: Uint8Array, size: number, hang = false) {
  const state = { closed: false };
  async function* gen(signal: AbortSignal) {
    try {
      for (let i = 0; i < data.length; i += size) { yield data.slice(i, i + size); await Promise.resolve(); }
      if (hang) await new Promise((_, reject) => signal.addEventListener("abort", () => reject(signal.reason), { once: true }));
    } finally { state.closed = true; }
  }
  return { state, open: gen };
}

// Every chunk size, LF and CRLF: splits inside multi-byte UTF-8 and inside the blank line.
for (let size = 1; size < 40; size++) {
  for (const data of [bytes, enc.encode(STREAM.replaceAll("\n", "\r\n"))]) {
    const s = source(data, size);
    const r = await consume(s.open, new Reply(), { deadlineMs: 5000 });
    assert.equal(r.status, "done");
    assert.equal(r.text, "Naïve café ✓ ok");
    assert.deepEqual(r.toolCalls(), [{ id: "call_1", name: "search", args: { q: "oled 65" } }]);
    assert.ok(s.state.closed);                           // [DONE] closed the upstream
  }
}

// Parser details.
{
  const p = new SSEParser();
  const evs = p.feed(enc.encode("event: ping\n\n: hi\nevent: delta\nid: 7\ndata:a\ndata: b\n\n"));
  assert.deepEqual(evs, [{ event: "delta", data: "a\nb", id: "7" }]);
  assert.deepEqual(p.feed(enc.encode("data: x\r")), []);
  assert.deepEqual(p.feed(enc.encode("\n\r\n")).map((e) => e.data), ["x"]);
}

const cut = enc.encode(STREAM.slice(0, STREAM.indexOf("d 65")));       // stops inside the second tool delta

// Timeout: partial text kept, no executable tool call, upstream closed.
{
  const s = source(cut, 16, true);
  const r = await consume(s.open, new Reply(), { deadlineMs: 20 });
  assert.equal(r.status, "timeout");
  assert.ok(r.text.endsWith("✓ ok"));
  assert.deepEqual(r.toolCalls(), []);
  assert.ok(s.state.closed);
}

// User cancel.
{
  const s = source(cut, 16, true);
  const user = new AbortController();
  const reply = new Reply();
  const p = consume(s.open, reply, { deadlineMs: 5000, signal: user.signal });
  while (!reply.text.endsWith("ok")) await new Promise((r) => setImmediate(r));
  user.abort();
  assert.equal((await p).status, "cancelled");
  assert.ok(s.state.closed);
}

// Server hung up without [DONE]: truncated, half-arrived arguments not run.
{
  const s = source(cut, 16);
  const r = await consume(s.open, new Reply(), { deadlineMs: 5000 });
  assert.equal(r.status, "truncated");
  assert.deepEqual(r.toolCalls(), []);
  assert.equal(r.calls.get(0)?.args, '{"q": "ole');
}

// Finished but malformed arguments come back as null.
{
  const r = new Reply();
  r.add({ choices: [{ delta: { tool_calls: [{ index: 0, id: "c", function: { name: "f", arguments: "{oops" } }] } }] });
  r.status = "done";
  assert.deepEqual(r.toolCalls(), [{ id: "c", name: "f", args: null }]);
}
console.log("builds-sse.ts: all tests passed");

# Exercise: a variant assignment service: sticky hash bucketing, Thompson sampling over Beta posteriors, idempotent hourly batches, an incubation floor, fail to control.
# Run its test: python interviews/coframe_builds/builds2-bandit_test.py
import hashlib
import random
from dataclasses import dataclass, field

CONTROL = "control"


def bucket(*parts: str) -> float:
    """Stable uniform in [0, 1) from the parts. No lookup table, same input same answer."""
    h = hashlib.sha256(":".join(parts).encode()).digest()
    return int.from_bytes(h[:8], "big") / 2**64


@dataclass
class Arm:
    a: float = 1.0          # 1 + conversions (Beta prior a0 = 1)
    b: float = 1.0          # 1 + non-conversions
    born_hour: int = 0      # for the incubation period


@dataclass
class State:
    experiment: str
    arms: dict[str, Arm]
    holdout: float = 0.10           # always control, for an unbiased baseline
    incubation_hours: int = 24
    floor: float = 0.10             # share each incubating arm is guaranteed
    version: int = 0                # bumps on every batch that changes a posterior
    seen: set[str] = field(default_factory=set)
    # ponytail: an in-memory seen set grows forever; in production it is a table with a
    # unique constraint on event_id (INSERT ... ON CONFLICT DO NOTHING) in the same transaction as the counts.


def assign(visitor: str, state: State | None, sticky: dict[str, str], hour: int) -> tuple[str, str]:
    """Return (arm, reason). sticky is the visitor's first assignment (a cookie or a row)."""
    if state is None:
        return CONTROL, "fallback"           # state unavailable: control, not sticky, not an exposure
    first = sticky.get(visitor)
    if first is not None:
        return (first, "sticky") if first in state.arms else (CONTROL, "retired")
    if bucket(state.experiment, "holdout", visitor) < state.holdout:
        arm, reason = CONTROL, "holdout"
    else:
        arm, reason = _draw(visitor, state, hour), "thompson"
    sticky[visitor] = arm
    return arm, reason


def _draw(visitor: str, state: State, hour: int) -> str:
    # Seeded by visitor and posterior version: a retry before the sticky write lands gets the same arm.
    rng = random.Random(int(bucket(state.experiment, str(state.version), visitor) * 2**53))
    young = sorted(k for k, arm in state.arms.items() if hour - arm.born_hour < state.incubation_hours)
    u = rng.random()
    if u < state.floor * len(young):
        return young[int(u / state.floor)]
    return max(sorted(state.arms), key=lambda k: rng.betavariate(state.arms[k].a, state.arms[k].b))


def apply_batch(state: State, events: list[dict]) -> dict[str, int]:
    """Hourly update. events: {id, arm, converted}. Replaying a batch changes nothing."""
    out = {"applied": 0, "duplicate": 0, "unknown_arm": 0}
    for e in events:
        if e["id"] in state.seen:
            out["duplicate"] += 1
            continue
        state.seen.add(e["id"])
        arm = state.arms.get(e["arm"])
        if arm is None:
            out["unknown_arm"] += 1
            continue
        if e["converted"]:
            arm.a += 1
        else:
            arm.b += 1
        out["applied"] += 1
    if out["applied"]:
        state.version += 1
    return out


def add_arm(state: State, name: str, hour: int, prior: tuple[float, float] = (1.0, 1.0)) -> None:
    state.arms[name] = Arm(prior[0], prior[1], hour)


def retire_arm(state: State, name: str) -> None:
    if name != CONTROL:
        state.arms.pop(name, None)

// Exercise: a variant assignment service: sticky hash bucketing, Thompson sampling (Beta via gamma variates), idempotent hourly batches, an incubation floor, fail to control.
// Run its test: node --experimental-strip-types interviews/coframe_builds/builds2-bandit.test.ts
import { createHash } from "node:crypto";

export const CONTROL = "control";

export type Arm = { a: number; b: number; bornHour: number };
export type State = {
  experiment: string;
  arms: Map<string, Arm>;
  holdout: number;
  incubationHours: number;
  floor: number;
  version: number;
  seen: Set<string>; // ponytail: grows forever; a unique event_id column in production
};
export type Event = { id: string; arm: string; converted: boolean };
export type Reason = "fallback" | "sticky" | "retired" | "holdout" | "thompson";

export function newState(experiment: string, arms: Record<string, [number, number]>): State {
  const m = new Map<string, Arm>();
  for (const [k, [a, b]] of Object.entries(arms)) m.set(k, { a, b, bornHour: 0 });
  return { experiment, arms: m, holdout: 0.1, incubationHours: 24, floor: 0.1, version: 0, seen: new Set() };
}

// Sync sha256 from node:crypto. At the edge (Workers) it is crypto.subtle.digest, which is async.
export function bucket(...parts: string[]): number {
  const h = createHash("sha256").update(parts.join(":")).digest();
  return h.readUInt32BE(0) / 2 ** 32;
}

// mulberry32: a small seeded PRNG, so a draw is reproducible. Math.random cannot be seeded.
export function rng(seed: number): () => number {
  let t = seed >>> 0;
  return () => {
    t = (t + 0x6d2b79f5) >>> 0;
    let x = Math.imul(t ^ (t >>> 15), 1 | t);
    x ^= x + Math.imul(x ^ (x >>> 7), 61 | x);
    return ((x ^ (x >>> 14)) >>> 0) / 2 ** 32;
  };
}

function normal(r: () => number): number {
  const u = 1 - r(); // (0, 1], so log is finite
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r());
}

// Marsaglia and Tsang (2000). For shape < 1, boost: Gamma(k) = Gamma(k + 1) * U^(1/k).
export function gamma(k: number, r: () => number): number {
  if (k < 1) return gamma(k + 1, r) * Math.pow(1 - r(), 1 / k);
  const d = k - 1 / 3;
  const c = 1 / Math.sqrt(9 * d);
  for (;;) {
    let x: number, v: number;
    do {
      x = normal(r);
      v = 1 + c * x;
    } while (v <= 0);
    v = v * v * v;
    const u = 1 - r();
    if (Math.log(u) < 0.5 * x * x + d - d * v + d * Math.log(v)) return d * v;
  }
}

// Beta(a, b) = X / (X + Y) with X ~ Gamma(a), Y ~ Gamma(b).
export function beta(a: number, b: number, r: () => number): number {
  const x = gamma(a, r);
  return x / (x + gamma(b, r));
}

export function assign(visitor: string, state: State | null, sticky: Map<string, string>, hour: number): [string, Reason] {
  if (state === null) return [CONTROL, "fallback"]; // not sticky, not an exposure
  const first = sticky.get(visitor);
  if (first !== undefined) return state.arms.has(first) ? [first, "sticky"] : [CONTROL, "retired"];
  let out: [string, Reason];
  if (bucket(state.experiment, "holdout", visitor) < state.holdout) out = [CONTROL, "holdout"];
  else out = [draw(visitor, state, hour), "thompson"];
  sticky.set(visitor, out[0]);
  return out;
}

function draw(visitor: string, state: State, hour: number): string {
  const r = rng(Math.floor(bucket(state.experiment, String(state.version), visitor) * 2 ** 32));
  const names = [...state.arms.keys()].sort();
  const young = names.filter((k) => hour - state.arms.get(k)!.bornHour < state.incubationHours);
  const u = r();
  if (u < state.floor * young.length) return young[Math.floor(u / state.floor)];
  let best = names[0];
  let top = -1;
  for (const k of names) {
    const arm = state.arms.get(k)!;
    const s = beta(arm.a, arm.b, r);
    if (s > top) [best, top] = [k, s];
  }
  return best;
}

export function applyBatch(state: State, events: Event[]): { applied: number; duplicate: number; unknownArm: number } {
  const out = { applied: 0, duplicate: 0, unknownArm: 0 };
  for (const e of events) {
    if (state.seen.has(e.id)) {
      out.duplicate++;
      continue;
    }
    state.seen.add(e.id);
    const arm = state.arms.get(e.arm);
    if (!arm) {
      out.unknownArm++;
      continue;
    }
    if (e.converted) arm.a++;
    else arm.b++;
    out.applied++;
  }
  if (out.applied) state.version++;
  return out;
}

export function addArm(state: State, name: string, hour: number, prior: [number, number] = [1, 1]): void {
  state.arms.set(name, { a: prior[0], b: prior[1], bornHour: hour });
}

export function retireArm(state: State, name: string): void {
  if (name !== CONTROL) state.arms.delete(name);
}

// Test for builds2-bandit.ts: node:assert, seeded randomness.
// Run: node --experimental-strip-types interviews/coframe_builds/builds2-bandit.test.ts
import assert from "node:assert/strict";
import { addArm, applyBatch, assign, beta, bucket, newState, retireArm, rng, type State } from "./builds2-bandit.ts";

function shares(st: State, n: number, hour: number, prefix = "v"): Record<string, number> {
  const c: Record<string, number> = {};
  for (let i = 0; i < n; i++) {
    const [arm] = assign(`${prefix}${i}`, st, new Map(), hour);
    c[arm] = (c[arm] ?? 0) + 1 / n;
  }
  return c;
}

// The beta sampler has the right mean: Beta(2, 8) has mean 0.2; Beta(0.5, 0.5) exercises shape < 1.
{
  const r = rng(42);
  let s = 0;
  for (let i = 0; i < 20000; i++) s += beta(2, 8, r);
  assert.ok(Math.abs(s / 20000 - 0.2) < 0.01);
  let t = 0;
  for (let i = 0; i < 20000; i++) t += beta(0.5, 0.5, r);
  assert.ok(Math.abs(t / 20000 - 0.5) < 0.02);
}

// Bucketing: stable, independent across experiments, holdout about 10%.
assert.equal(bucket("hero", "u1"), bucket("hero", "u1"));
assert.notEqual(bucket("hero", "u1"), bucket("other", "u1"));
{
  const st = newState("hero", { control: [1, 1], v1: [1, 1] });
  let h = 0;
  for (let i = 0; i < 20000; i++) if (assign(`h${i}`, st, new Map(), 100)[1] === "holdout") h++;
  assert.ok(h / 20000 > 0.09 && h / 20000 < 0.11);
}

// Sticky: posteriors move, the first assignment does not.
{
  const st = newState("hero", { control: [1, 1], v1: [1, 1] });
  const sticky = new Map<string, string>();
  const first = new Map<string, string>();
  for (let i = 0; i < 200; i++) first.set(`s${i}`, assign(`s${i}`, st, sticky, 100)[0]);
  applyBatch(st, Array.from({ length: 500 }, (_, i) => ({ id: `e${i}`, arm: "v1", converted: true })));
  for (const [v, arm] of first) assert.equal(assign(v, st, sticky, 101)[0], arm);
  assert.deepEqual(assign("r1", st, new Map(), 101), assign("r1", st, new Map(), 101));
}

// Replaying a batch is a no-op.
{
  const st = newState("hero", { control: [1, 1], v1: [1, 1] });
  const batch = Array.from({ length: 100 }, (_, i) => ({ id: `b${i}`, arm: "v1", converted: i % 10 === 0 }));
  assert.deepEqual(applyBatch(st, batch), { applied: 100, duplicate: 0, unknownArm: 0 });
  assert.deepEqual(applyBatch(st, batch), { applied: 0, duplicate: 100, unknownArm: 0 });
  const v1 = st.arms.get("v1")!;
  assert.deepEqual([v1.a, v1.b, st.version], [11, 91, 1]);
}

// Thompson favours the better arm; the incubation floor protects a young unlucky arm.
{
  const st = newState("hero", { control: [501, 9501], v1: [801, 9201] });
  assert.ok(shares(st, 5000, 100).v1 > 0.85);
  addArm(st, "v2", 100, [1, 61]);
  const young = shares(st, 5000, 110).v2 ?? 0;
  const old = shares(st, 5000, 130).v2 ?? 0;
  assert.ok(young > 0.07 && young < 0.13, String(young));
  assert.ok(old < 0.03, String(old));
}

// Fail to control; retired arm.
assert.deepEqual(assign("x", null, new Map([["x", "v1"]]), 100), ["control", "fallback"]);
{
  const st = newState("hero", { control: [1, 1], v1: [1, 1] });
  retireArm(st, "v1");
  assert.deepEqual(assign("x", st, new Map([["x", "v1"]]), 100), ["control", "retired"]);
}

// End to end: ten hourly batches against true rates, seeded.
{
  const r = rng(7);
  const truth: Record<string, number> = { control: 0.04, v1: 0.07 };
  const st = newState("hero", { control: [1, 1], v1: [1, 1] });
  let id = 0;
  for (let hour = 100; hour < 110; hour++) {
    const events = [];
    for (let i = 0; i < 2000; i++) {
      const [arm] = assign(`h${hour}-${i}`, st, new Map(), hour);
      events.push({ id: `ev${id++}`, arm, converted: r() < truth[arm] });
    }
    applyBatch(st, events);
  }
  assert.ok(shares(st, 2000, 110, "final").v1 > 0.7);
}

