# Exercise: from flat span events, build each run's tree; wall time, cost, tokens, the critical path, failing tool calls; a summary an agent can read to fix itself.
# Run its test: python interviews/coframe_builds/builds2-traces_test.py
from collections import defaultdict

LEAF_KINDS = ("llm", "tool")   # sum cost here only: a parent span may carry a roll-up, summing it double counts


def build(spans: list[dict]) -> dict[str, dict]:
    """Group by run, index children, find roots. A span whose parent never arrived is an orphan root."""
    runs: dict[str, dict] = {}
    for s in spans:
        run = runs.setdefault(s["run_id"], {"spans": {}, "kids": defaultdict(list), "roots": [], "orphans": []})
        run["spans"].setdefault(s["span_id"], s)          # duplicate delivery: keep the first
    for run in runs.values():
        for s in run["spans"].values():
            pid = s.get("parent_id")
            if pid is None:
                run["roots"].append(s)
            elif pid in run["spans"]:
                run["kids"][pid].append(s)
            else:
                run["roots"].append(s)                     # parent dropped by sampling or still in flight
                run["orphans"].append(s["span_id"])
        for k in run["kids"].values():
            k.sort(key=lambda s: s["start"])
    return runs


def critical_path(span: dict, kids: dict) -> list[dict]:
    """Walk back from the span's end: the child that finished last is what it waited for; repeat before its start."""
    chosen, t = [], max([span["end"]] + [c["end"] for c in kids.get(span["span_id"], [])])
    for c in sorted(kids.get(span["span_id"], []), key=lambda c: c["end"], reverse=True):
        if c["end"] <= t:
            chosen.insert(0, c)
            t = c["start"]
    out = [span]
    for c in chosen:
        out += critical_path(c, kids)
    return out


def analyse(run_id: str, run: dict) -> dict:
    spans = list(run["spans"].values())
    leaves = [s for s in spans if s.get("kind") in LEAF_KINDS]
    root = min(run["roots"], key=lambda s: s["start"])
    path = critical_path(root, run["kids"]) if len(run["roots"]) == 1 else []
    failures = []
    for s in spans:
        if s.get("kind") == "tool" and s.get("status") == "error":
            # ponytail: O(failures x spans) scan for a later successful sibling; index by (parent, name) for huge runs
            later_ok = any(o["name"] == s["name"] and o.get("parent_id") == s.get("parent_id")
                           and o["start"] >= s["end"] and o.get("status") == "ok" for o in spans)
            failures.append({"span": s, "recovered": later_ok})
    failures.sort(key=lambda f: f["span"]["start"])
    t0 = min(s["start"] for s in spans)
    failed = root.get("status") == "error" or any(not f["recovered"] for f in failures)
    return {
        "run_id": run_id,
        "status": "error" if failed else "ok",
        "wall": max(s["end"] for s in spans) - t0,          # not the sum: parallel tool calls overlap
        "cost": sum(s.get("cost") or 0 for s in leaves),
        "tokens": sum(s.get("tokens") or 0 for s in spans if s.get("kind") == "llm"),
        "spans": len(spans),
        "path": [s for s in path if s.get("kind") in LEAF_KINDS],
        "failures": failures,
        "orphans": run["orphans"],
        "t0": t0,
    }


def summary(a: dict) -> str:
    """Compact on purpose: it goes into an agent's context, so every line must earn its tokens."""
    lines = [f"run {a['run_id']}: {a['status']} | wall {a['wall']:.1f}s | cost ${a['cost']:.4f} | "
             f"tokens {a['tokens']:,} | {a['spans']} spans"]
    if a["path"]:
        lines.append("critical path: " + " > ".join(
            f"{s['name']} ({s['kind']} {s['end'] - s['start']:.1f}s)" for s in a["path"]))
    else:
        lines.append("critical path: unknown (several roots)")
    for f in a["failures"]:
        s = f["span"]
        tag = "recovered by retry" if f["recovered"] else "NOT recovered"
        lines.append(f"failed tool: {s['name']} at +{s['start'] - a['t0']:.1f}s: {s.get('error', 'no message')} ({tag})")
    if a["orphans"]:
        lines.append(f"warning: {len(a['orphans'])} span(s) with a missing parent: {', '.join(a['orphans'])}")
    return "\n".join(lines)


def report(spans: list[dict]) -> str:
    runs = build(spans)
    return "\n\n".join(summary(analyse(rid, runs[rid])) for rid in sorted(runs))

// Exercise: from flat span events, build each run's tree; wall time, cost, tokens, the critical path, failing tool calls; a summary an agent can read to fix itself.
// Run its test: node --experimental-strip-types interviews/coframe_builds/builds2-traces.test.ts

export type Span = {
  run_id: string;
  span_id: string;
  parent_id: string | null;
  name: string;
  kind: "llm" | "tool" | "agent";
  start: number; // seconds
  end: number;
  tokens?: number;
  cost?: number;
  status: "ok" | "error";
  error?: string;
};
type Run = { spans: Map<string, Span>; kids: Map<string, Span[]>; roots: Span[]; orphans: string[] };
export type Failure = { span: Span; recovered: boolean };
export type Analysis = {
  runId: string;
  status: "ok" | "error";
  wall: number;
  cost: number;
  tokens: number;
  spans: number;
  path: Span[];
  failures: Failure[];
  orphans: string[];
  t0: number;
};

const isLeaf = (s: Span) => s.kind === "llm" || s.kind === "tool"; // a parent may carry a roll-up: never sum it

export function build(spans: Span[]): Map<string, Run> {
  const runs = new Map<string, Run>();
  for (const s of spans) {
    let run = runs.get(s.run_id);
    if (!run) runs.set(s.run_id, (run = { spans: new Map(), kids: new Map(), roots: [], orphans: [] }));
    if (!run.spans.has(s.span_id)) run.spans.set(s.span_id, s); // duplicate delivery: keep the first
  }
  for (const run of runs.values()) {
    for (const s of run.spans.values()) {
      if (s.parent_id === null) run.roots.push(s);
      else if (run.spans.has(s.parent_id)) {
        const k = run.kids.get(s.parent_id) ?? [];
        k.push(s);
        run.kids.set(s.parent_id, k);
      } else {
        run.roots.push(s); // parent dropped by sampling or still in flight
        run.orphans.push(s.span_id);
      }
    }
  }
  return runs;
}

// Walk back from the span's end: the child that finished last is what it waited for; repeat before its start.
export function criticalPath(span: Span, kids: Map<string, Span[]>): Span[] {
  const children = kids.get(span.span_id) ?? [];
  let t = Math.max(span.end, ...children.map((c) => c.end));
  const chosen: Span[] = [];
  for (const c of [...children].sort((x, y) => y.end - x.end)) {
    if (c.end <= t) {
      chosen.unshift(c);
      t = c.start;
    }
  }
  return [span, ...chosen.flatMap((c) => criticalPath(c, kids))];
}

export function analyse(runId: string, run: Run): Analysis {
  const spans = [...run.spans.values()];
  const root = run.roots.reduce((a, b) => (b.start < a.start ? b : a));
  const path = run.roots.length === 1 ? criticalPath(root, run.kids) : [];
  const failures: Failure[] = spans
    .filter((s) => s.kind === "tool" && s.status === "error")
    .map((s) => ({
      span: s,
      recovered: spans.some((o) => o.name === s.name && o.parent_id === s.parent_id && o.start >= s.end && o.status === "ok"),
    }))
    .sort((a, b) => a.span.start - b.span.start);
  const t0 = Math.min(...spans.map((s) => s.start));
  const failed = root.status === "error" || failures.some((f) => !f.recovered);
  return {
    runId,
    status: failed ? "error" : "ok",
    wall: Math.max(...spans.map((s) => s.end)) - t0, // not the sum: parallel calls overlap
    cost: spans.filter(isLeaf).reduce((n, s) => n + (s.cost ?? 0), 0),
    tokens: spans.filter((s) => s.kind === "llm").reduce((n, s) => n + (s.tokens ?? 0), 0),
    spans: spans.length,
    path: path.filter(isLeaf),
    failures,
    orphans: run.orphans,
    t0,
  };
}

// Compact on purpose: it goes into an agent's context, so every line must earn its tokens.
export function summary(a: Analysis): string {
  const lines = [
    `run ${a.runId}: ${a.status} | wall ${a.wall.toFixed(1)}s | cost $${a.cost.toFixed(4)} | tokens ${a.tokens.toLocaleString("en-US")} | ${a.spans} spans`,
    a.path.length
      ? "critical path: " + a.path.map((s) => `${s.name} (${s.kind} ${(s.end - s.start).toFixed(1)}s)`).join(" > ")
      : "critical path: unknown (several roots)",
  ];
  for (const { span: s, recovered } of a.failures) {
    lines.push(`failed tool: ${s.name} at +${(s.start - a.t0).toFixed(1)}s: ${s.error ?? "no message"} (${recovered ? "recovered by retry" : "NOT recovered"})`);
  }
  if (a.orphans.length) lines.push(`warning: ${a.orphans.length} span(s) with a missing parent: ${a.orphans.join(", ")}`);
  return lines.join("\n");
}

export function report(spans: Span[]): string {
  const runs = build(spans);
  return [...runs.keys()].sort().map((id) => summary(analyse(id, runs.get(id)!))).join("\n\n");
}

// Test for builds2-traces.ts: node:assert on a hand-built trace.
// Run: node --experimental-strip-types interviews/coframe_builds/builds2-traces.test.ts
import assert from "node:assert/strict";
import { analyse, build, report, type Span } from "./builds2-traces.ts";

const sp = (run_id: string, span_id: string, parent_id: string | null, name: string, kind: Span["kind"], start: number, end: number,
  extra: Partial<Span> = {}): Span => ({ run_id, span_id, parent_id, name, kind, start, end, tokens: 0, cost: 0, status: "ok", ...extra });

const SPANS: Span[] = [
  sp("r1", "a", null, "variant_run", "agent", 0, 10, { cost: 0.036, status: "error" }),
  sp("r1", "b", "a", "plan", "llm", 0, 1, { tokens: 1200, cost: 0.006 }),
  sp("r1", "c", "a", "fetch_page", "tool", 1, 3, { status: "error", error: "timeout after 2s" }),
  sp("r1", "d", "a", "lint", "tool", 1, 2),
  sp("r1", "e", "a", "fetch_page", "tool", 3, 5),
  sp("r1", "f", "a", "write_variant", "llm", 5, 9, { tokens: 3000, cost: 0.03 }),
  sp("r1", "g", "a", "run_tests", "tool", 9, 10, { status: "error", error: "2 failed: test_cta_visible" }),
  sp("r1", "b", "a", "plan", "llm", 0, 1, { tokens: 1200, cost: 0.006 }),
  sp("r2", "s0", null, "research", "agent", 0, 4),
  sp("r2", "s1", "s0", "subagent", "agent", 0, 4),
  sp("r2", "s2", "s1", "plan", "llm", 0, 1, { tokens: 500, cost: 0.002 }),
  sp("r2", "s3", "s1", "search_a", "tool", 1, 3, { cost: 0.001 }),
  sp("r2", "s4", "s1", "search_b", "tool", 1, 4, { cost: 0.001 }),
  sp("r3", "x0", null, "run", "agent", 0, 2),
  sp("r3", "x1", "ghost", "late_tool", "tool", 1, 2),
];

const runs = build(SPANS);
const r1 = analyse("r1", runs.get("r1")!);
assert.equal(r1.spans, 7);
assert.equal(r1.wall, 10);
assert.ok(Math.abs(r1.cost - 0.036) < 1e-9);
assert.equal(r1.tokens, 4200);
assert.deepEqual(r1.path.map((s) => s.span_id), ["b", "c", "e", "f", "g"]);
assert.deepEqual(r1.failures.map((f) => [f.span.span_id, f.recovered]), [["c", true], ["g", false]]);
assert.equal(r1.status, "error");

const r2 = analyse("r2", runs.get("r2")!);
assert.equal(r2.wall, 4);
assert.deepEqual(r2.path.map((s) => s.name), ["plan", "search_b"]);
assert.ok(Math.abs(r2.cost - 0.004) < 1e-9);

const r3 = analyse("r3", runs.get("r3")!);
assert.deepEqual(r3.orphans, ["x1"]);
assert.deepEqual(r3.path, []);

const text = report(SPANS);
console.log(text);
assert.ok(text.includes("run r1: error | wall 10.0s | cost $0.0360 | tokens 4,200 | 7 spans"));
assert.ok(text.includes("critical path: plan (llm 1.0s) > fetch_page (tool 2.0s) > fetch_page (tool 2.0s) > write_variant (llm 4.0s) > run_tests (tool 1.0s)"));
assert.ok(text.includes("failed tool: run_tests at +9.0s: 2 failed: test_cta_visible (NOT recovered)"));
assert.ok(text.includes("warning: 1 span(s) with a missing parent: x1"));
console.log("builds2-traces.ts: ok");
